#!/usr/bin/env bash
set -e

# Restore signing keystore from GitHub Secret, repository files, or embedded fallback
if [ -n "${SIGNING_KEYSTORE_BASE64}" ]; then
  echo "Restoring keystore from GitHub Secret SIGNING_KEYSTORE_BASE64..."
  echo "${SIGNING_KEYSTORE_BASE64}" | tr -d '\r\n' | base64 -d > debug.keystore
elif [ -f "signing/debug.keystore.base64" ]; then
  echo "Restoring keystore from committed signing/debug.keystore.base64..."
  cat signing/debug.keystore.base64 | tr -d '\r\n' | base64 -d > debug.keystore
elif [ -f "debug.keystore.base64" ]; then
  echo "Restoring keystore from committed debug.keystore.base64..."
  cat debug.keystore.base64 | tr -d '\r\n' | base64 -d > debug.keystore
else
  echo "Restoring keystore from embedded fallback..."
  cat << 'EOF' | tr -d '\r\n' | base64 -d > debug.keystore

EOF
fi

# Verify keystore is valid and print SHA-256 fingerprint in build logs
keytool -list -v -keystore debug.keystore -storepass android | grep -E "(Alias name|SHA256:)" || true
